"""Migration of the Meridian CRM 4.2 order_fulfilment workflow."""

from decimal import Decimal
from typing import Any, Callable


Guard = Callable[[dict, dict], bool]


def _numeric(value: Any) -> Decimal:
    """Apply the legacy empty-value numeric coercion."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _approve_guard(record: dict, tables: dict) -> bool:
    # NVL(TOT_AMT, 0) > 0
    return _numeric(record.get("TOT_AMT", "")) > Decimal("0")


def _lookup(
    tables: dict,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Return the first matching live row's value, or the legacy empty string."""
    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_column, "") == key_value:
            value = row.get(output_column, "")
            return "" if value is None else value
    return ""


def _approved_cancel_guard(record: dict, tables: dict) -> bool:
    # LOOKUP(ACCT_MASTER, ACCT_ID, ACCT_ID, CRED_HOLD) <> 'Y'
    credit_hold = _lookup(
        tables,
        "ACCT_MASTER",
        "ACCT_ID",
        record.get("ACCT_ID", ""),
        "CRED_HOLD",
    )
    return credit_hold != "Y"


def _always(record: dict, tables: dict) -> bool:
    return True


# Document order is significant: the first matching transition fires.
_TRANSITIONS: tuple[
    tuple[str, str, str, Guard, tuple[tuple[str, str], ...]], ...
] = (
    ("E", "approve", "A", _approve_guard, (("audit", "ORD_APPR"),)),
    (
        "A",
        "ship",
        "S",
        _always,
        (("audit", "ORD_SHIP"), ("notify", "shipped")),
    ),
    ("S", "invoice", "I", _always, (("audit", "ORD_INV"),)),
    ("E", "cancel", "X", _always, (("audit", "ORD_CANC"),)),
    (
        "A",
        "cancel",
        "X",
        _approved_cancel_guard,
        (("audit", "ORD_CANC"),),
    ),
    (
        "I",
        "cancel",
        "X",
        _always,
        (("audit", "ORD_CANC_INV"), ("notify", "credit_note")),
    ),
)


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire one order_fulfilment workflow event without mutating the input."""
    record_copy = dict(record)

    for from_state, transition_event, to_state, guard, actions in _TRANSITIONS:
        if state != from_state or event != transition_event:
            continue
        if not guard(record_copy, tables):
            continue

        audits: list[str] = []
        notifies: list[str] = []

        for action_type, value in actions:
            if action_type == "audit":
                audits.append(value)
            elif action_type == "notify":
                notifies.append(value)

        return {
            "state": to_state,
            "record": record_copy,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": record_copy,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
